document.addEventListener('DOMContentLoaded', () => {
    console.log('%c🩸 Обсессия — тренажёр загружен', 'color:#8b0000;font-size:20px;font-weight:bold;');
    initTrainer();
    initFloatingFx();
});

function initTrainer() {
    const newBtn = document.getElementById('new-text');
    const box = document.getElementById('target-text');
    const hidden = document.getElementById('hidden-input');
    const langSel = document.getElementById('lang-select');
    const lenSel = document.getElementById('len-select');

    if (!newBtn) return;

    // Клик по тексту → фокус на скрытый input
    box.addEventListener('click', () => hidden.focus());
    box.addEventListener('focus', () => hidden.focus());

    // Автофокус при вводе
    hidden.addEventListener('input', onType);
    hidden.addEventListener('blur', () => {
        setTimeout(() => { if (isActive) hidden.focus(); }, 10);
    });

    newBtn.addEventListener('click', () => {
        pickRandomText(langSel.value, lenSel.value);
        hidden.focus();
    });

    document.getElementById('btn-close').addEventListener('click', () => {
        document.getElementById('result-modal').classList.remove('active');
        pickRandomText(langSel.value, lenSel.value);
        hidden.focus();
    });

    document.getElementById('btn-screenshot').addEventListener('click', takeScreenshot);

    // Фокус при клике в любое место карточки тренажёра
    document.querySelector('.trainer').addEventListener('click', (e) => {
        if (e.target.closest('select') || e.target.closest('button')) return;
        hidden.focus();
        box.classList.add('active');
    });

    document.addEventListener('click', (e) => {
        if (!e.target.closest('.trainer')) {
            box.classList.remove('active');
        }
    });

    pickRandomText('ru', 'short');
}

let isActive = false;
let startTime = null;
let timerInterval = null;
let chars = [];
let currentText = "";
let correctTyped = 0;
let totalTyped = 0;

function pickRandomText(lang, len) {
    const pool = TEXTS[lang][len];
    currentText = pool[Math.floor(Math.random() * pool.length)];
    chars = currentText.split('');
    const hidden = document.getElementById('hidden-input');
    hidden.value = '';
    isActive = false;
    correctTyped = 0;
    totalTyped = 0;
    if (timerInterval) clearInterval(timerInterval);
    startTime = null;
    document.getElementById('timer').textContent = '0';
    document.getElementById('wpm').textContent = '0';
    document.getElementById('accuracy').textContent = '100';
    document.getElementById('target-text').classList.remove('active');
    renderText();
}

function renderText() {
    const box = document.getElementById('target-text');
    const typed = document.getElementById('hidden-input').value;
    let html = '';
    for (let i = 0; i < chars.length; i++) {
        let cls = 'char';
        if (chars[i] === ' ') cls += ' space';
        if (i < typed.length) {
            cls += typed[i] === chars[i] ? ' correct' : ' wrong';
        } else if (i === typed.length) {
            cls += ' current';
        }
        const ch = chars[i] === ' ' ? '&nbsp;' : chars[i].replace(/&/g, '&amp;').replace(/</g, '&lt;');
        html += `<span class="${cls}">${ch}</span>`;
    }
    box.innerHTML = html;
}

function onType() {
    const hidden = document.getElementById('hidden-input');
    const typed = hidden.value;
    const box = document.getElementById('target-text');

    if (!isActive && typed.length > 0) {
        isActive = true;
        box.classList.add('active');
        startTime = Date.now();
        if (timerInterval) clearInterval(timerInterval);
        timerInterval = setInterval(updateTimer, 200);
    }

    if (!isActive) return;

    correctTyped = 0;
    for (let i = 0; i < typed.length && i < chars.length; i++) {
        if (typed[i] === chars[i]) correctTyped++;
    }

    totalTyped = typed.length;
    const acc = typed.length ? Math.round((correctTyped / typed.length) * 100) : 100;
    document.getElementById('accuracy').textContent = acc;
    renderText();

    if (typed.length >= chars.length) finishTyping();
}

function updateTimer() {
    if (!startTime) return;
    const elapsed = Math.floor((Date.now() - startTime) / 1000);
    document.getElementById('timer').textContent = elapsed;
    const minutes = elapsed / 60;
    if (minutes > 0) {
        const wpm = Math.round((correctTyped / 5) / minutes);
        document.getElementById('wpm').textContent = wpm;
    }
}

function finishTyping() {
    if (timerInterval) clearInterval(timerInterval);
    isActive = false;
    const elapsed = startTime ? Math.floor((Date.now() - startTime) / 1000) : 0;
    const minutes = elapsed / 60;
    const wpm = minutes > 0 ? Math.round((correctTyped / 5) / minutes) : 0;
    const accuracy = chars.length ? Math.round((correctTyped / chars.length) * 100) : 0;

    document.getElementById('r-wpm').textContent = wpm;
    document.getElementById('r-accuracy').textContent = accuracy;
    document.getElementById('r-time').textContent = elapsed;
    document.getElementById('r-chars').textContent = chars.length;

    // Рандомная картинка
    const imgEl = document.getElementById('result-photo-img');
    if (imgEl && typeof RESULT_IMAGES !== 'undefined') {
        const randImg = RESULT_IMAGES[Math.floor(Math.random() * RESULT_IMAGES.length)];
        imgEl.src = randImg;
        console.log('[Result] Рандомная картинка:', randImg);
    }

    // Рандомная цитата
    document.getElementById('result-joke').textContent =
        JOKES[Math.floor(Math.random() * JOKES.length)];

    setTimeout(() => {
        document.getElementById('result-modal').classList.add('active');
    }, 300);
}

// ===== Плавающий фон =====
function initFloatingFx() {
    const bubbles = document.getElementById('blood-bubbles');
    if (bubbles) {
        for (let i = 0; i < 22; i++) spawnBubble(bubbles);
    }
    setInterval(spawnBloodDrop, 700);
}

function spawnBubble(container) {
    const b = document.createElement('div');
    b.className = 'blood-bubble';
    const size = 15 + Math.random() * 45;
    b.style.width = size + 'px';
    b.style.height = size + 'px';
    b.style.left = Math.random() * 100 + 'vw';
    b.style.animationDuration = (14 + Math.random() * 16) + 's';
    b.style.animationDelay = (-Math.random() * 20) + 's';
    container.appendChild(b);
}

function spawnBloodDrop() {
    const d = document.createElement('div');
    d.className = 'blood-drop';
    d.style.left = Math.random() * 100 + 'vw';
    const dur = 3.5 + Math.random() * 4;
    d.style.animationDuration = dur + 's';
    d.style.height = (14 + Math.random() * 20) + 'px';
    document.body.appendChild(d);
    setTimeout(() => d.remove(), (dur + 1) * 1000);
}

