// ===== Скриншот =====
async function takeScreenshot() {
    console.log('[Screenshot] Копирую в буфер');
    const card = document.getElementById('result-card');
    const btn = document.getElementById('btn-screenshot');
    if (!card || !btn) return;
    if (typeof html2canvas === 'undefined') {
        alert('html2canvas не загружен. Обнови (Ctrl+F5).');
        return;
    }

    const oldText = btn.textContent;
    btn.textContent = '⏳ Копирую...';
    btn.disabled = true;

    try {
        const canvas = await html2canvas(card, {
            backgroundColor: '#1a0000',
            scale: 2,
            useCORS: true,
            allowTaint: true,
            logging: false
        });

        canvas.toBlob(async (blob) => {
            if (!blob) {
                showToast('❌ Не удалось сформировать');
                btn.textContent = oldText;
                btn.disabled = false;
                return;
            }
            let copied = false;
            if (navigator.clipboard && window.ClipboardItem) {
                try {
                    await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
                    copied = true;
                    showToast('✅ Скопировано в буфер обмена!');
                } catch (e) {
                    console.error('Clipboard error:', e);
                }
            }
            if (!copied) {
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'obsession-result-' + Date.now() + '.png';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
                showToast('💾 Файл скачан в Загрузки');
            }
            btn.textContent = '✅ Готово!';
            setTimeout(() => { btn.textContent = oldText; btn.disabled = false; }, 2000);
        }, 'image/png', 0.95);

    } catch (err) {
        console.error('[Screenshot]', err);
        showToast('❌ Ошибка: ' + (err.message || err));
        btn.textContent = oldText;
        btn.disabled = false;
    }
}

/* Всплывающее уведомление */
function showToast(message) {
    const t = document.createElement('div');
    t.textContent = message;
    t.style.cssText = `
        position: fixed;
        top: 30px;
        left: 50%;
        transform: translateX(-50%) translateY(-100px);
        background: linear-gradient(135deg, #8b0000, #c1121f);
        color: white;
        padding: 14px 26px;
        border-radius: 8px;
        font-family: 'Courier New', monospace;
        font-weight: bold;
        letter-spacing: 1px;
        box-shadow: 0 0 30px rgba(193,18,31,0.8), 0 8px 20px rgba(0,0,0,0.6);
        z-index: 99999;
        border: 1px solid #e63946;
        transition: transform 0.35s ease;
        pointer-events: none;
    `;
    document.body.appendChild(t);
    requestAnimationFrame(() => {
        t.style.transform = 'translateX(-50%) translateY(0)';
    });
    setTimeout(() => {
        t.style.transform = 'translateX(-50%) translateY(-100px)';
        setTimeout(() => t.remove(), 400);
    }, 2500);
}
